<template><div class="page"><h1>{{ t('房产列表') }}</h1><div class="row" style="margin:18px 0"><el-input v-model="filters.q" :placeholder="t('地址或地块编号')" style="width:240px" @keyup.enter="load(true)"/><el-input v-model="filters.suburb" :placeholder="t('区域')" style="width:160px" @keyup.enter="load(true)"/><el-select v-model="filters.registered" style="width:125px"><el-option :label="t('全部登记')" value=""/><el-option :label="t('已登记')" value="true"/><el-option :label="t('未登记')" value="false"/></el-select><el-select v-model="filters.hasOwner" style="width:150px"><el-option :label="t('全部产权')" value=""/><el-option :label="t('有产权信息')" value="true"/><el-option :label="t('无产权信息')" value="false"/></el-select><el-input-number v-model="filters.minYearsHeld" :min="0" :max="200" style="width:140px"/><el-button @click="load(true)">{{ t('筛选') }}</el-button></div><el-table :data="items" class="card" @row-click="select"><el-table-column prop="address" :label="t('地址')"/><el-table-column prop="suburb" :label="t('区域')"/><el-table-column prop="lotplan" :label="t('地块')"/><el-table-column :label="t('已登记')"><template #default="{row}">{{ row.registered?t('是'):t('否') }}</template></el-table-column><el-table-column prop="ownerNames" :label="t('业主姓名')"/><el-table-column prop="lastSalePrice" :label="t('上次成交价')"/><el-table-column prop="lastSaleDate" :label="t('上次成交日期')"/><el-table-column prop="yearsHeld" :label="t('持有年数')"/><el-table-column :label="t('异地业主')"><template #default="{row}">{{ row.absenteeOwner?t('是'):t('否') }}</template></el-table-column><el-table-column :label="t('覆盖经纪人')"><template #default="{row}">{{ row.coveringAgents?.map(a=>a.name).join(', ') }}</template></el-table-column></el-table><el-button style="margin-top:14px" :disabled="!cursor" @click="load()">{{ t('下一页') }}</el-button><AdminParcelDrawer :parcel="selected" @close="selected=null"/></div></template><script setup>import {reactive,ref,onMounted,watch} from 'vue';import {useRoute} from 'vue-router';import {api} from '../api';import {t} from '../i18n';import AdminParcelDrawer from '../components/AdminParcelDrawer.vue';const route=useRoute(),filters=reactive({q:'',suburb:'',registered:'',hasOwner:'',minYearsHeld:0}),items=ref([]),cursor=ref(''),selected=ref(null);async function load(reset=false){if(reset)cursor.value='';const q=new URLSearchParams();for(const [k,v] of Object.entries(filters))if(v)q.set(k,v);if(cursor.value)q.set('cursor',cursor.value);const rows=await api('admin/properties?'+q);items.value=rows;cursor.value=rows.length===50?rows.at(-1).id:''}function select(row){selected.value=row}watch(()=>route.query.q,v=>{filters.q=v||'';load(true)});onMounted(()=>{filters.q=route.query.q||'';load(true)})</script>
